                post_hook={
                    "sql": "create or replace table maplemonk.KA_Secondary_sales_consolidated_intermediate as select cast(b.customer_id as string) customer_id ,null region ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(coalesce(GA4.channel, b.FINAL_UTM_CHANNEL)) AS CHANNEL ,Upper(coalesce(GA4.final_source, b.source,b.FINAL_UTM_SOURCE)) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(b.shipping_status, c.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,c.awb,d.awb) AWB ,UPPER(GATEWAY) PAYMENT_GATEWAY ,upper(coalesce(c.payment_mode,d.payment_mode)) Payment_Mode ,Upper(coalesce(c.Courier,d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as datetime),cast(timestamp(c.manifest_date) as datetime),cast(timestamp(d.dispatch_date) as datetime)) AS DISPATCH_DATE ,coalesce(cast(timestamp(c.delivered_date) as datetime),cast(timestamp(d.delivered_date) as datetime),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as datetime) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(b.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,b.SKU_CODE commonsku ,upper(coalesce(c.warehouse_name,d.warehouse_name)) WAREHOUSE ,coalesce(b.pincode,d.pincode,c.pincode) as pincode ,coalesce(c.pickup_pincode,fa.pincode) as source_pincode from maplemonk.KA_SHOPIFY_FACT_ITEMS b left join ( select transactionid, final_source, channel from maplemonk.KA_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) =1 ) GA4 on replace(b.order_name,\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from maplemonk.KA_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(b.order_name,\'#\',\'\') = c.reference_code and b.LINE_ITEM_ID=c.Marketplace_LineItem_ID left join (select * from (select * ,row_number() over (partition by order_id, SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] order by shipping_last_update_date desc) rw from maplemonk.KA_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) UNION ALL SELECT cast(NULL AS string) customer_id, \'INDIA\' REGION, UPPER(afi.SHOP_NAME) AS Shop_name, \'AMAZON\' AS marketplace, \'AMAZON\' AS CHANNEL, \'AMAZON\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, NULL AS PHONE, afi.NAME, COALESCE(EEFI.EMAIL, UFI.EMAIL, AFI.EMAIL) AS EMAIL, COALESCE( CAST(EEFI.shipping_last_update_date AS timestamp), CAST(UFI.shipping_last_update_date AS timestamp) ) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, cast(afi.PRODUCT_ID as string) PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS datetime) Order_Time, afi.QUANTITY, IFNULL(TOTAL_SALES, 0) - IFNULL(afi.tax, 0) + IFNULL(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, case when MRP.MRP is null then AFI.DISCOUNT_BEFORE_TAX else (ifnull(mrp.mrp,0)*afi.quantity - IFNULL(AFI.TOTAL_SALES, 0)) end AS DISCOUNT, afi.TAX, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(EEFI.order_status, UFI.order_status)) AS OMS_order_status, UPPER(COALESCE(EEFI.shipping_status, UFI.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALEORDERITEMCODE, CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS SALES_ORDER_ITEM_ID, COALESCE(EEFI.awb, UFI.awb) AS AWB, NULL AS Payment_Gateway, UPPER(COALESCE(EEFI.payment_mode, UFI.payment_mode)) AS Payment_Mode, UPPER(COALESCE(EEFI.Courier, UFI.courier)) AS COURIER, cast(COALESCE(EEFI.manifest_date, UFI.dispatch_date) as datetime) AS DISPATCH_DATE, cast(COALESCE(EEFI.delivered_date , UFI.delivered_date ) as datetime) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status, EEFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, afi.IS_REFUND AS RETURN_FLAG, CASE WHEN afi.is_refund = 1 THEN CAST(afi.quantity AS INT64) END AS returned_quantity, CASE WHEN afi.is_refund = 1 THEN afi.total_sales END AS returned_sales, CASE WHEN afi.is_refund = 0 AND LOWER(afi.order_status) = \'cancelled\' THEN CAST(afi.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, E