) over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) UNION ALL select cast(null as string) customer_id ,REGION ,shop_name ,marektplace ,CHANNEL ,SOURCE ,ORDER_ID ,reference_code ,cast(null as string) PHONE ,cast(null as string) NAME ,cast(null as string) EMAIL ,cast(SHIPPING_LAST_UPDATE_DATE as timestamp) SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,CURRENCY ,cast(null as string) city ,cast(null as string) State ,cast(null as string) order_status ,Order_Date ,ORDER_TIME ,QUANTITY ,gross_sales_before_tax ,DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE ,cast(null as string) OMS_ORDER_STATUS ,cast(null as string) SHIPPING_STATUS ,cast(null as string) FINAL_SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,AWB ,payment_gateway ,payment_mode ,COURIER ,cast(null as datetime) DISPATCH_DATE ,cast(null as datetime) delivered_date ,cast(null as int64) DELIVERED_STATUS ,cast(null as int64) RETURN_FLAG ,cast(null as int64) returned_quantity ,cast(null as float64) returned_sales ,cast(null as int64) cancelled_quantity ,NEW_CUSTOMER_FLAG ,ACQUISITION_PRODUCT ,cast(null as int64) days_in_shipment ,cast(null as date) ACQUISITION_DATE ,sku_code ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,PRODUCT_SUB_CATEGORY ,commonsku ,warehouse ,pincode ,source_pincode from maplemonk.KA_AMAZON_VENDOR_CENTRAL_FACT_ITEMS UNION ALL select cast(null as string) customer_id ,REGION ,shop_name ,marektplace ,CHANNEL ,SOURCE ,ORDER_ID ,reference_code ,cast(null as string) PHONE ,cast(null as string) NAME ,cast(