arketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,cast(MANIFEST_DATE as datetime) AS DISPATCH_DATE ,cast(DELIVERED_DATE as datetime) ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,NULL AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(mapped_category) AS PRODUCT_CATEGORY ,UPPER(mapped_sub_category) AS PRODUCT_SUB_CATEGORY ,b.SKU commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,pickup_pincode FROM maplemonk.KA_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' or LOWER(marketplace) LIKE ANY (\'%amazon%\', \'%gofynd\') ) UNION ALL SELECT cast(NULL as string) AS customer_id ,\'INDIA\' REGION ,UPPER(case when lower(marketplace) like \'custom\' then \'WEBSITE INDIA\' else marketplace end) AS shop_name ,UPPER(case when lower(marketplace) like \'custom\' then \'WEBSITE INDIA\' else marketplace end) AS marketplace ,UPPER(case when lower(marketplace) like \'custom\' then coalesce(GA4.channel, \'UTM NA IN GA\') else marketplace end) AS CHANNEL ,UPPER(case when lower(marketplace) like \'custom\' then coalesce(GA4.final_source,\'UTM NA IN GA\') else marketplace end) AS SOURCE ,ORDER_ID ,reference_code ,phone AS PHONE ,name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS city ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS order_status ,CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,case when MRP.MRP is null then b.discount else (ifnull(mrp.mrp,0)*b.suborder_quantity - IFNULL(SELLING_PRICE, 0)) end AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(b.Product_Category) AS PRODUCT_CATEGORY ,UPPER(b.Product_Sub_Category) AS PRODUCT_SUB_CATEGORY ,b.commonsku ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode source_pincode FROM maplemonk.KA_unicommerce_fact_items b left join (select COMMONSKUCODE , parse_date(\'%d-%b-%y\',START_DATE) start_Date , parse_date(\'%d-%b-%y\',END_DATE) End_Date , cast(MRP AS FLOAT64) MRP , cast(COGS AS FLOAT64) COGS from maplemonk.ka_gs_sku_mrp_cogs qualify row_number() over (partition by lower(commonskucode), start_date, end_date order by 1) =1 ) mrp on lower(b.commonsku) = lower(mrp.commonskucode) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT Join ( select transactionid ,Final_Source ,Channel from maplemonk.KA_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) = 1 ) GA4 on b.reference_code = GA4.transactionid LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE (LOWER(b.marketplace) LIKE ANY (\'%website%\', \'%flipkart%\')) union all SELECT cast(NULL AS string) customer_id, REGION, UPPER(afiu.SHOP_NAME) AS Shop_name, \'AMAZON SELLER CENTRAL US\' AS marketplace, \'AMAZON SELLER CENTRAL US\' AS CHANNEL, \'AMAZON SELLER CENTRAL US\' AS SOURCE, afiu.ORDER_ID, afiu.ORDER_ID AS reference_code, NULL AS PHONE, afiu.NAME, AFIU.EMAIL, AFIU.LAST_UPDATED_DATE SHIPPING_LAST_UPDATE_DATE, AFIU.SKU, cast(AFIU.PRODUCT_ID as string) PRODUCT_ID, AFIU.PRODUCT_NAME, AFIU.CURRENCY, UPPER(AFIU.CITY) AS CITY, UPPER(AFIU.STATE) AS State, UPPER(AFIU.ORDER_STATUS) AS Order_Status, CAST(AFIU.order_timestamp_PST AS DATE) AS Order_Date, CAST(AFIU.order_timestamp_PST AS datetime) Order_Time, AFIU.QUANTITY, IFNULL(TOTAL_SALES_INR, 0) - IFNULL(AFIU.tax_INR, 0) + IFNULL(DISCOUNT_BEFORE_TAX_INR, 0) AS GROSS_SALES_BEFORE_TAX_INR, case when MRP.MRP is null or ifnull(mrp.mrp,0)*AFIU.quantity < ifnull(TOTAL_SALES_INR,0) then AFIU.DISCOUNT_BEFORE_TAX_INR else (ifnull(mrp.mrp,0)*AFIU.quantity - IFNULL(AFIU.TOTAL_SALES_INR, 0)) end AS DISCOUNT_INR, AFIU.TAX_INR, AFIU.SHIPPING_PRICE_INR, TOTAL_SALES_INR AS SELLING_PRICE, NULL AS OMS_order_status, AFIU.ORDER_STATUS AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, AFIU.Order_status)) AS FINAL_SHIPPING_STATUS, CONCAT(AFIU.ORDER_ID, \'-\', AFIU.PRODUCT_ID) AS SALEORDERITEMCODE, CONCAT(AFIU.ORDER_ID, \'-\', AFIU.PRODUCT_ID) AS SALES_ORDER_ITEM_ID, NULL AWB, NULL AS Payment_Gateway, NULL AS Payment_Mode, NULL AS COURIER, cast(NULL as datetime) AS DISPATCH_DATE, cast(NULL as datetime) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, AFIU.Order_Status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, AFIU.IS_REFUND AS RETURN_FLAG, CASE WHEN AFIU.is_refund = 1 THEN CAST(AFIU.quantity AS INT64) END AS returned_quantity, CASE WHEN AFIU.is_refund = 1 THEN AFIU.total_sales_INR END AS returned_sales, CASE WHEN AFIU.is_refund = 0 AND LOWER(AFIU.order_status) = \'cancelled\' THEN CAST(AFIU.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, AFIU.Order_Status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(AFIU.ORDER_TIMESTAMP_PST AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, AFIU.Order_Status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(AFIU.ORDER_TIMESTAMP_PST AS DATE), DAY) END AS Days_in_Shipment, NULL AS A