PRICE_INR,0) SELLING_PRICE_INR ,cast(NULL as string) AS OMS_ORDER_STATUS ,BC.Order_Status AS SHIPPING_STATUS ,coalesce(SHIPMAP.final_shipping_status, BC.Order_Status) AS FINAL_SHIPPING_STATUS ,cast(BC.SALEORDERITEMCODE as string) SALEORDERITEMCODE ,cast(BC.SALES_ORDER_ITEM_ID as string) SALES_ORDER_ITEM_ID ,NULL AWB ,PAYMENT_METHOD AS payment_gateway ,PAYMENT_METHOD payment_mode ,NULL courier ,cast(BC.ORDER_SHIPPED_DATE_IST as datetime) AS DISPATCH_DATE ,case when BC.order_status = \'COMPLETED\' then cast(BC.ORDER_MODIFIED_DATE_IST as datetime) else cast(null as datetime) end AS delivered_date ,case when BC.order_status = \'COMPLETED\' then 1 else 0 end Delivered_status ,BC.RETURN_FLAG ,cast(BC.Refund_Quantity as int64) Refund_Quantity ,BC.Refund_Amount_INR ,case when BC.order_status = \'CANCELLED\' then cast(BC.QUANTITY as INT64) else 0 end cancelled_quantity ,null NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, BC.Order_Status)) IN (\'completed\',\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(BC.ORDER_TIMESTAMP_IST AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.final_shipping_status, BC.Order_Status)) IN (\'in transit\', \'shipment created\',\'shipped\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(BC.ORDER_TIMESTAMP_IST AS DATE), DAY) END AS Days_in_Shipment ,cast(NULL as date) AS ACQUISITION_DATE ,BC.SKU ,UPPER(BC.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(BC.Product_Category) AS PRODUCT_CATEGORY ,UPPER(BC.Product_Sub_Category) AS PRODUCT_SUB_CATEGORY ,BC.commonsku ,null warehouse ,BC.pincode ,null source_pincode from MAPLEMONK.KA_US_BIGCOMMERCE_FACT_ITEMS BC left join (select COMMONSKUCODE , parse_date(\'%d-%b-%y\',START_DATE) start_Date , parse_date(\'%d-%b-%y\',END_DATE) End_Date , cast(MRP AS FLOAT64) MRP , cast(COGS AS FLOAT64) COGS from maplemonk.ka_gs_sku_mrp_cogs qualify row_number() over (partition by lower(commonskucode), start_date, end_date order by 1) =1 ) mrp on lower(BC.commonsku) = lower(mrp.commonskucode) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(BC.ORDER_STATUS) = LOWER(ShipMap.shipping_status) ; CREATE OR REPLACE TABLE maplemonk.Secondary_Sales_Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM maplemonk.KA_Secondary_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM maplemonk.KA_Secondary_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.KA_secondary_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.KA_Secondary_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.Secondary_Sales_Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.Secondary_Sales_Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE maplemonk.KA_secondary_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.KA_secondary_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.KA_secondary_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.KA_secondary_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.KA_secondary_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.KA_secondary_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.KA_secondary_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.KA_secondary_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM maplemonk.KA_secondary_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE maplemonk.KA_secondary_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE maplemonk.KA_secondary_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM maplemonk.KA_secondary_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.KA_secondary_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final;",
                    "transaction": true
